package secondbrain.domain.test;

import secondbrain.domain.context.RagMultiDocumentContext;
import secondbrain.infrastructure.llm.LlmClient;

import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Function;

/**
 * An LLM client for unit tests. Every request is recorded, and the response to each prompt is generated by a
 * function of the request, which may also throw to simulate a failed call. Expose it with a @Produces @Preferred
 * method.
 */
public final class RecordingLlmClient implements LlmClient {
    public record Request(RagMultiDocumentContext<?> document, Map<String, String> environmentSettings, String tool) {
    }

    public final List<Request> requests = new CopyOnWriteArrayList<>();
    private volatile Function<RagMultiDocumentContext<?>, String> responder = document -> "answer";

    /**
     * Generate responses with the supplied function. Throw from the function to make the call fail.
     */
    public RecordingLlmClient respondWith(final Function<RagMultiDocumentContext<?>, String> responder) {
        this.responder = responder;
        return this;
    }

    @Override
    public String call(final String prompt, final Map<String, String> environmentSettings) {
        return callWithCache(new RagMultiDocumentContext<Void>(prompt), environmentSettings, "").getResponse();
    }

    @Override
    public String call(final String prompt, final String model, final Map<String, String> environmentSettings) {
        return call(prompt, environmentSettings);
    }

    @Override
    public <T> RagMultiDocumentContext<T> callWithCache(final RagMultiDocumentContext<T> ragDoc, final Map<String, String> environmentSettings, final String tool) {
        requests.add(new Request(ragDoc, environmentSettings, tool));
        return ragDoc.updateResponse(responder.apply(ragDoc));
    }
}
